public with sharing class OverdueInvoiceBatch
    implements Database.Batchable<FB_Invoice__c>, Database.Stateful {

    private Integer recordsUpdated = 0;
    private Integer recordsFailed = 0;
    private Decimal overdueAmount = 0;

    public OverdueInvoiceBatch() {
    }

    public Database.QueryLocator start(Database.BatchableContext context) {
        Date today = Date.today();

        return Database.getQueryLocator([
            SELECT Id, Status__c, Amount__c
            FROM FB_Invoice__c
            WHERE Status__c = 'Open'
                AND Due_Date__c < :today
        ]);
    }

    public void execute(
        Database.BatchableContext context,
        List<FB_Invoice__c> scope
    ) {
        if (scope.isEmpty()) {
            return;
        }

        // Sparse updates avoid writing unrelated fields from the queried records.
        List<FB_Invoice__c> updates = new List<FB_Invoice__c>();
        for (FB_Invoice__c invoice : scope) {
            updates.add(new FB_Invoice__c(
                Id = invoice.Id,
                Status__c = 'Overdue'
            ));
        }

        // Allow individual invoices to fail without rolling back successful rows.
        Database.SaveResult[] results = Database.update(updates, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (results[i].isSuccess()) {
                recordsUpdated++;
                if (scope[i].Amount__c != null) {
                    overdueAmount += scope[i].Amount__c;
                }
            } else {
                recordsFailed++;
            }
        }
    }

    public void finish(Database.BatchableContext context) {
        insert new FB_Job_Summary__c(
            Job_Name__c = 'OverdueInvoiceBatch',
            Records_Updated__c = recordsUpdated,
            Records_Failed__c = recordsFailed,
            Overdue_Amount__c = overdueAmount
        );
    }
}
