public with sharing class ExchangeRateClient {
    public class ExchangeRateException extends Exception {}

    public static Map<String, Decimal> getRates(
        String baseCurrency,
        Set<String> quoteCurrencies
    ) {
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException(
                'At least one quote currency is required.'
            );
        }

        String normalizedBase = normalizeCurrency(baseCurrency);
        Set<String> normalizedQuotes = new Set<String>();

        // Complete all input validation before making a callout.
        for (String quoteCurrency : quoteCurrencies) {
            normalizedQuotes.add(normalizeCurrency(quoteCurrency));
        }

        List<String> quoteCodes = new List<String>(normalizedQuotes);
        quoteCodes.sort();

        HttpRequest request = new HttpRequest();
        // Validated codes contain only A-Z; commas are safe query separators.
        request.setEndpoint(
            'callout:FB_Exchange_Rates/v1/latest?base=' +
            normalizedBase +
            '&symbols=' +
            String.join(quoteCodes, ',')
        );
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        request.setTimeout(10000);

        HttpResponse response;
        Http http = new Http();

        try {
            response = http.send(request);
            if (response.getStatusCode() == 503) {
                // Reuse the identical request, retrying at most once.
                response = http.send(request);
            }
        } catch (System.CalloutException ex) {
            throw new ExchangeRateException(
                'The exchange rate callout failed.',
                ex
            );
        }

        Integer statusCode = response.getStatusCode();
        if (statusCode != 200) {
            throw new ExchangeRateException(
                'The exchange rate service returned HTTP ' + statusCode + '.'
            );
        }

        return parseRates(response.getBody(), quoteCodes);
    }

    private static String normalizeCurrency(String currencyCode) {
        String normalized = currencyCode == null
            ? null
            : currencyCode.trim().toUpperCase();

        if (
            normalized == null ||
            !Pattern.matches('^[A-Z]{3}$', normalized)
        ) {
            throw new ExchangeRateException(
                'Each currency code must contain exactly three letters A-Z.'
            );
        }

        return normalized;
    }

    private static Map<String, Decimal> parseRates(
        String body,
        List<String> requestedCodes
    ) {
        try {
            Map<String, Object> payload =
                (Map<String, Object>) JSON.deserializeUntyped(body);

            Map<String, Object> responseRates = payload == null
                ? null
                : (Map<String, Object>) payload.get('rates');

            if (responseRates == null) {
                throw new ExchangeRateException(
                    'The exchange rate response is missing rates.'
                );
            }

            Map<String, Decimal> result = new Map<String, Decimal>();
            for (String code : requestedCodes) {
                Object rawRate = responseRates.get(code);

                if (rawRate == null) {
                    throw new ExchangeRateException(
                        'The exchange rate response has no rate for ' + code + '.'
                    );
                }

                if (
                    !(rawRate instanceof Decimal) &&
                    !(rawRate instanceof Integer) &&
                    !(rawRate instanceof Long) &&
                    !(rawRate instanceof Double)
                ) {
                    throw new ExchangeRateException(
                        'The exchange rate response has an invalid rate for ' +
                        code + '.'
                    );
                }

                result.put(code, Decimal.valueOf(String.valueOf(rawRate)));
            }

            return result;
        } catch (ExchangeRateException ex) {
            throw ex;
        } catch (Exception ex) {
            throw new ExchangeRateException(
                'The exchange rate response could not be parsed.',
                ex
            );
        }
    }
}
