public with sharing class ContactDomainService {
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        // Do not mutate the caller's set or include contacts without an account.
        Set<Id> nonNullAccountIds = new Set<Id>(accountIds);
        nonNullAccountIds.remove(null);

        if (nonNullAccountIds.isEmpty()) {
            return contactsByDomain;
        }

        // User mode also enforces object and field permissions.
        for (Contact contactRecord : [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :nonNullAccountIds
                AND Email != null
            WITH USER_MODE
        ]) {
            if (String.isBlank(contactRecord.Email)) {
                continue;
            }

            String email = contactRecord.Email.trim();
            Integer separatorIndex = email.lastIndexOf('@');

            if (separatorIndex <= 0 || separatorIndex == email.length() - 1) {
                continue;
            }

            String domain = email.substring(separatorIndex + 1).toLowerCase();

            if (!contactsByDomain.containsKey(domain)) {
                contactsByDomain.put(domain, new List<Contact>());
            }

            contactsByDomain.get(domain).add(contactRecord);
        }

        return contactsByDomain;
    }
}
