public with sharing class RecordSearchService {
    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            if (String.isBlank(objectApiName)) {
                throw new SearchException('An object API name is required.');
            }
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('At least one requested field is required.');
            }
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }

            // Global describe maps support case-insensitive API-name lookup.
            Schema.SObjectType objectType = Schema.getGlobalDescribe()
                .get(objectApiName.toLowerCase());

            if (objectType == null) {
                throw new SearchException('The specified object does not exist.');
            }

            Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();
            if (!objectDescribe.isAccessible()) {
                throw new SearchException('You do not have read access to this object.');
            }
            if (!objectDescribe.isQueryable()) {
                throw new SearchException('This object cannot be queried.');
            }

            Map<String, Schema.SObjectField> fieldsByLowerName =
                new Map<String, Schema.SObjectField>();
            Map<String, Schema.SObjectField> describedFields =
                objectDescribe.fields.getMap();

            for (String fieldName : describedFields.keySet()) {
                fieldsByLowerName.put(
                    fieldName.toLowerCase(),
                    describedFields.get(fieldName)
                );
            }

            // Id is always selected, so its read access must also be checked.
            Schema.DescribeFieldResult idField =
                requireReadableField('Id', fieldsByLowerName);

            List<String> selectFields = new List<String>{ idField.getName() };
            Set<String> selectedNames = new Set<String>{
                idField.getName().toLowerCase()
            };

            for (String requestedField : fields) {
                Schema.DescribeFieldResult fieldDescribe =
                    requireReadableField(requestedField, fieldsByLowerName);
                String canonicalName = fieldDescribe.getName();

                // Avoid duplicate selections, including a requested Id.
                if (!selectedNames.contains(canonicalName.toLowerCase())) {
                    selectFields.add(canonicalName);
                    selectedNames.add(canonicalName.toLowerCase());
                }
            }

            Map<String, Object> binds = new Map<String, Object>{
                'rowLimit' => maxRows
            };
            List<String> conditions = new List<String>();
            Integer bindIndex = 0;

            if (filters != null) {
                for (String filterField : filters.keySet()) {
                    Schema.DescribeFieldResult fieldDescribe =
                        requireReadableField(filterField, fieldsByLowerName);

                    if (!fieldDescribe.isFilterable()) {
                        throw new SearchException(
                            'A filter field does not support filtering.'
                        );
                    }

                    String bindName = 'filterValue' + bindIndex;
                    bindIndex++;

                    // Preserve the supplied type, including null. Never
                    // concatenate filter values into the SOQL text.
                    binds.put(bindName, filters.get(filterField));
                    conditions.add(fieldDescribe.getName() + ' = :' + bindName);
                }
            }

            String canonicalOrderBy;
            if (String.isNotBlank(orderByField)) {
                Schema.DescribeFieldResult orderField =
                    requireReadableField(orderByField, fieldsByLowerName);

                if (!orderField.isSortable()) {
                    throw new SearchException(
                        'The order-by field does not support sorting.'
                    );
                }
                canonicalOrderBy = orderField.getName();
            }

            // Only schema-validated, canonical identifiers enter the query.
            String soql =
                'SELECT ' + String.join(selectFields, ', ') +
                ' FROM ' + objectDescribe.getName();

            if (!conditions.isEmpty()) {
                soql += ' WHERE ' + String.join(conditions, ' AND ');
            }
            if (canonicalOrderBy != null) {
                soql += ' ORDER BY ' + canonicalOrderBy + ' ASC';
            }
            soql += ' LIMIT :rowLimit';

            // Enforces sharing, CRUD, FLS, and applicable restriction rules.
            return Database.queryWithBinds(soql, binds, AccessLevel.USER_MODE);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            // Normalize query errors, including incompatible filter values
            // and any additional user-mode access failures.
            throw new SearchException(
                'The search could not be completed. Check the filter values ' +
                'and your access permissions.'
            );
        }
    }

    private static Schema.DescribeFieldResult requireReadableField(
        String fieldApiName,
        Map<String, Schema.SObjectField> fieldsByLowerName
    ) {
        if (String.isBlank(fieldApiName)) {
            throw new SearchException('A field API name is missing or invalid.');
        }

        Schema.SObjectField fieldToken =
            fieldsByLowerName.get(fieldApiName.toLowerCase());

        if (fieldToken == null) {
            throw new SearchException(
                'A specified field does not exist on the object.'
            );
        }

        Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
        if (!fieldDescribe.isAccessible()) {
            throw new SearchException(
                'You do not have read access to a field involved in the search.'
            );
        }
        return fieldDescribe;
    }
}
