public with sharing class ContactLookupAction {
    public class Request {
        @InvocableVariable(required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable
        public Id contactId;

        @InvocableVariable
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        List<String> normalizedEmails = new List<String>();
        Set<String> emailsToQuery = new Set<String>();

        for (Request request : requests) {
            String normalizedEmail =
                request == null || String.isBlank(request.email)
                ? null
                : request.email.trim().toLowerCase();

            normalizedEmails.add(normalizedEmail);
            if (normalizedEmail != null) {
                emailsToQuery.add(normalizedEmail);
            }
        }

        Map<String, Id> firstContactByEmail = new Map<String, Id>();

        if (!emailsToQuery.isEmpty()) {
            // Email comparisons are case-insensitive. User mode also enforces
            // object and field permissions, in addition to record sharing.
            for (Contact contactRecord : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :emailsToQuery
                WITH USER_MODE
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String emailKey = contactRecord.Email.toLowerCase();

                // Keep the earliest contact; Id breaks CreatedDate ties.
                if (!firstContactByEmail.containsKey(emailKey)) {
                    firstContactByEmail.put(emailKey, contactRecord.Id);
                }
            }
        }

        // Preserve input cardinality and order, including duplicate emails.
        for (String normalizedEmail : normalizedEmails) {
            Result result = new Result();
            result.contactId = normalizedEmail == null
                ? null
                : firstContactByEmail.get(normalizedEmail);
            result.found = result.contactId != null;
            results.add(result);
        }

        return results;
    }
}
