public with sharing class OrderPayloadParser {
    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines = new List<Line>();
        public Decimal total = 0;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount = 0;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('The request body must not be blank.');
        }

        try {
            JSONParser parser = JSON.createParser(body);
            parser.nextToken();
            expectToken(
                parser,
                JSONToken.START_OBJECT,
                'The payload must be a JSON object.'
            );

            Order result = new Order();

            while (parser.nextToken() != JSONToken.END_OBJECT) {
                String propertyName = readPropertyName(parser);

                switch on propertyName {
                    when 'number' {
                        result.orderNumber = readString(parser, 'number');
                    }
                    when 'date' {
                        result.orderDate = readDate(parser);
                    }
                    when 'currency' {
                        result.currencyCode = readString(parser, 'currency');
                    }
                    when 'customer' {
                        result.customerEmail = readCustomerEmail(parser);
                    }
                    when 'lines' {
                        result.lines = readLines(parser);
                    }
                    when else {
                        parser.skipChildren();
                    }
                }
            }

            // Reject trailing content, including a second JSON document.
            if (parser.nextToken() != null) {
                throw new PayloadException('Unexpected content after the payload.');
            }

            if (String.isBlank(result.orderNumber)) {
                throw new PayloadException('number is required and must not be blank.');
            }

            // Sum the individually rounded line totals.
            for (Line line : result.lines) {
                result.total += line.lineTotal;
            }

            return result;
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            // Normalize JSON, numeric and date conversion errors.
            throw new PayloadException('Invalid order payload.');
        }
    }

    public static String toAcknowledgement(Order order) {
        if (order == null || order.total == null) {
            throw new PayloadException('An order with a total is required.');
        }

        Integer lineCount = order.lines == null ? 0 : order.lines.size();

        return JSON.serialize(new Map<String, Object>{
            'number' => order.orderNumber,
            'status' => 'RECEIVED',
            'lineCount' => lineCount,
            'total' => order.total
        });
    }

    private static List<Line> readLines(JSONParser parser) {
        List<Line> result = new List<Line>();

        if (parser.getCurrentToken() == JSONToken.VALUE_NULL) {
            return result;
        }

        expectToken(
            parser,
            JSONToken.START_ARRAY,
            'lines must be an array or null.'
        );

        while (parser.nextToken() != JSONToken.END_ARRAY) {
            result.add(readLine(parser));
        }

        return result;
    }

    private static Line readLine(JSONParser parser) {
        expectToken(
            parser,
            JSONToken.START_OBJECT,
            'Each line must be a JSON object.'
        );

        Line result = new Line();

        while (parser.nextToken() != JSONToken.END_OBJECT) {
            String propertyName = readPropertyName(parser);

            switch on propertyName {
                when 'sku' {
                    result.sku = readString(parser, 'sku');
                }
                when 'quantity' {
                    result.quantity = readQuantity(parser);
                }
                when 'unitPrice' {
                    result.unitPrice = readDecimal(parser, 'unitPrice');
                }
                when 'discount' {
                    Decimal discount = readDecimal(parser, 'discount');
                    result.discount = discount == null ? 0 : discount;
                }
                when else {
                    parser.skipChildren();
                }
            }
        }

        if (String.isBlank(result.sku)) {
            throw new PayloadException('Each line requires a nonblank sku.');
        }
        if (result.quantity == null || result.quantity <= 0) {
            throw new PayloadException('Each line requires a positive quantity.');
        }
        if (result.unitPrice == null || result.unitPrice < 0) {
            throw new PayloadException('Each line requires a nonnegative unitPrice.');
        }
        if (result.discount < 0 || result.discount > 1) {
            throw new PayloadException('discount must be between 0 and 1.');
        }

        result.lineTotal = (
            result.quantity * result.unitPrice * (1 - result.discount)
        ).setScale(2, System.RoundingMode.HALF_UP);

        return result;
    }

    private static String readCustomerEmail(JSONParser parser) {
        if (parser.getCurrentToken() == JSONToken.VALUE_NULL) {
            return null;
        }

        expectToken(
            parser,
            JSONToken.START_OBJECT,
            'customer must be an object or null.'
        );

        String email;
        while (parser.nextToken() != JSONToken.END_OBJECT) {
            String propertyName = readPropertyName(parser);

            if (propertyName == 'email') {
                email = readString(parser, 'customer.email');
            } else {
                parser.skipChildren();
            }
        }

        return email;
    }

    // Called on a field-name token; leaves the parser on its value.
    private static String readPropertyName(JSONParser parser) {
        expectToken(
            parser,
            JSONToken.FIELD_NAME,
            'Expected a JSON property name.'
        );

        String propertyName = parser.getText();
        if (parser.nextToken() == null) {
            throw new PayloadException('Expected a JSON property value.');
        }

        return propertyName;
    }

    private static String readString(JSONParser parser, String fieldName) {
        if (parser.getCurrentToken() == JSONToken.VALUE_NULL) {
            return null;
        }

        expectToken(
            parser,
            JSONToken.VALUE_STRING,
            fieldName + ' must be a string or null.'
        );

        return parser.getText();
    }

    private static Decimal readDecimal(JSONParser parser, String fieldName) {
        JSONToken token = parser.getCurrentToken();

        if (token == JSONToken.VALUE_NULL) {
            return null;
        }
        if (
            token != JSONToken.VALUE_NUMBER_INT &&
            token != JSONToken.VALUE_NUMBER_FLOAT
        ) {
            throw new PayloadException(fieldName + ' must be a JSON number.');
        }

        // Read directly as Decimal to avoid binary floating-point rounding.
        return parser.getDecimalValue();
    }

    private static Integer readQuantity(JSONParser parser) {
        Decimal value = readDecimal(parser, 'quantity');

        if (value == null) {
            return null;
        }
        if (
            value <= 0 ||
            value > 2147483647 ||
            value != value.setScale(0, System.RoundingMode.DOWN)
        ) {
            throw new PayloadException(
                'quantity must be a positive integer within the Integer range.'
            );
        }

        return value.intValue();
    }

    private static Date readDate(JSONParser parser) {
        String value = readString(parser, 'date');

        if (value == null) {
            return null;
        }
        if (!Pattern.matches('[0-9]{4}-[0-9]{2}-[0-9]{2}', value)) {
            throw new PayloadException('date must use yyyy-MM-dd format.');
        }

        return Date.newInstance(
            Integer.valueOf(value.substring(0, 4)),
            Integer.valueOf(value.substring(5, 7)),
            Integer.valueOf(value.substring(8, 10))
        );
    }

    private static void expectToken(
        JSONParser parser,
        JSONToken expected,
        String message
    ) {
        if (parser.getCurrentToken() != expected) {
            throw new PayloadException(message);
        }
    }
