                for (String zone : zoneSpellings[zoneIndex]) {
                    for (Decimal orderValue : belowThreshold) {
                        assertQuote(standardPrice, weightKg, zone, false, orderValue);
                        assertQuote(standardPrice, weightKg, zone, null, orderValue);
                        assertQuote(expressPrice, weightKg, zone, true, orderValue);
