                    // Only domestic standard shipping becomes free.
                    Decimal highValueStandardPrice = standardPrice;
                    if (zoneIndex == 0) {
                        highValueStandardPrice = 0;
                    }

                    for (Decimal orderValue : qualifyingValues) {
                        assertQuote(
                            highValueStandardPrice, weightKg, zone, false, orderValue
                        );
                        assertQuote(
                            highValueStandardPrice, weightKg, zone, null, orderValue
                        );
                        assertQuote(expressPrice, weightKg, zone, true, orderValue);
                    }
