            Assert.areEqual(
                wanted.CloseDate, opportunity.CloseDate, message + ': CloseDate'
            );
        }
    }

    private static Map<Id, String> ratingsOf(List<Account> accounts) {
        Map<Id, String> result = new Map<Id, String>();
        for (Account accountRecord : accounts) {
            result.put(accountRecord.Id, accountRecord.Rating);
        }
        return result;
    }

    private static void assertRatings(Map<Id, String> expected) {
        Set<Id> ids = expected.keySet();
        List<Account> actual = [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :ids
        ];
        Assert.areEqual(expected.size(), actual.size());
        for (Account accountRecord : actual) {
            Assert.areEqual(
                expected.get(accountRecord.Id),
                accountRecord.Rating,
                'Account Rating: ' + accountRecord.Id
            );
        }
    }

    private class WorkBudget {
        private Integer queriesBefore;
        private Integer statementsBefore;
        private Integer rowsBefore;

        WorkBudget() {
            queriesBefore = Limits.getQueries();
            statementsBefore = Limits.getDmlStatements();
            rowsBefore = Limits.getDmlRows();
        }

        void assertDelta(Integer statements, Integer rows) {
            Integer queriesUsed = Limits.getQueries() - queriesBefore;
            Assert.isTrue(
                queriesUsed <= 1,
                'Expected at most one handler query; used ' + queriesUsed
            );
            Assert.areEqual(
                statements,
                Limits.getDmlStatements() - statementsBefore,
                'DML statement count, including the initiating Opportunity DML'
            );
            Assert.areEqual(
                rows,
                Limits.getDmlRows() - rowsBefore,
                'DML row count; already-Hot and unrelated Accounts must not be updated'
            );
        }
    }

