public with sharing class PicklistService {
    private static Map<String, Schema.SObjectType> objectTypes;

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {
    }

    /**
     * Returns active field-level options in their defined order.
     * Options are not filtered by record type or controlling-field value.
     */
    public static List<PicklistService.Option> activeOptions(
        String objectApiName,
        String fieldApiName
    ) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException(
                'Object API name must not be null or blank.'
            );
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException(
                'Field API name must not be null or blank.'
            );
        }

        // Cache the global describe map for this transaction.
        if (objectTypes == null) {
            objectTypes = Schema.getGlobalDescribe();
        }

        String objectName = objectApiName.trim();
        String fieldName = fieldApiName.trim();

        Schema.SObjectType objectType =
            objectTypes.get(objectName.toLowerCase());
        if (objectType == null) {
            throw new PicklistServiceException(
                'Object does not exist: ' + objectName
            );
        }

        Map<String, Schema.SObjectField> fields = objectType
            .getDescribe(Schema.SObjectDescribeOptions.DEFERRED)
            .fields.getMap();

        Schema.SObjectField fieldToken = fields.get(fieldName.toLowerCase());
        if (fieldToken == null) {
            throw new PicklistServiceException(
                'Field does not exist: ' + objectName + '.' + fieldName
            );
        }

        Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (
            fieldType != Schema.DisplayType.Picklist &&
            fieldType != Schema.DisplayType.MultiPicklist
        ) {
            throw new PicklistServiceException(
                'Field is not a picklist or multi-select picklist: ' +
                objectName + '.' + fieldName
            );
        }

        List<PicklistService.Option> options =
            new List<PicklistService.Option>();

        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (entry.isActive()) {
                options.add(new Option(
                    entry.getValue(),
                    entry.getLabel(),
                    entry.isDefaultValue()
                ));
            }
        }

        return options;
    }
}
