public with sharing class AccountScoringJob implements Queueable {
    private static final Integer CHUNK_SIZE = 200;

    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds == null
            ? new List<Id>()
            : accountIds.clone();
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }

        // Explicit root depth overrides the Developer Edition default and
        // supports execution of the complete chain in Apex tests.
        System.AsyncOptions options = new System.AsyncOptions();
        options.MaximumQueueableStackDepth =
            (accountIds.size() + CHUNK_SIZE - 1) / CHUNK_SIZE;

        return System.enqueueJob(new AccountScoringJob(accountIds), options);
    }

    public void execute(QueueableContext context) {
        if (accountIds.isEmpty()) {
            return;
        }

        Integer chunkSize = Math.min(CHUNK_SIZE, accountIds.size());
        List<Id> chunkIds = new List<Id>();
        for (Integer i = 0; i < chunkSize; i++) {
            chunkIds.add(accountIds[i]);
        }

        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :chunkIds
            WITH USER_MODE
        ];

        List<Account> updates = new List<Account>();
        for (Account account : accounts) {
            Decimal revenue = account.AnnualRevenue;
            String rating = 'Cold';

            if (revenue != null && revenue >= 1000000) {
                rating = 'Hot';
            } else if (revenue != null && revenue >= 100000) {
                rating = 'Warm';
            }

            // Only Rating is submitted for update; AnnualRevenue is read-only
            // for this operation.
            updates.add(new Account(
                Id = account.Id,
                Rating = rating
            ));
        }

        update as user updates;

        if (chunkSize < accountIds.size()) {
            List<Id> remainingIds = new List<Id>();
            for (Integer i = chunkSize; i < accountIds.size(); i++) {
                remainingIds.add(accountIds[i]);
            }

            if (System.isQueueable()) {
                // Children inherit the root's configured maximum stack depth.
                System.enqueueJob(new AccountScoringJob(remainingIds));
            } else {
                // A direct execute(null) call must establish a configured root
                // for its remaining work rather than rely on the default depth.
                start(remainingIds);
            }
        }
    }
}
