public with sharing class ErpSyncFinalizer implements Finalizer {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null
            ? new Set<Id>()
            : new Set<Id>(accountIds);
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(FinalizerContext context) {
        Boolean succeeded =
            context.getResult() == System.ParentJobResult.SUCCESS;

        FB_Job_Log__c logRecord = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Status__c = succeeded ? 'Success' : 'Failed',
            Attempt__c = attempt
        );

        if (!succeeded) {
            Exception failure = context.getException();
            String errorMessage = failure == null
                ? null
                : failure.getMessage();

            if (errorMessage != null) {
                logRecord.Error__c = errorMessage.left(255);
            }
        }

        // Infrastructure logging intentionally uses system-mode DML.
        // The finalizer transaction survives rollback of the parent job.
        insert logRecord;

        if (!succeeded && attempt < 3) {
            System.enqueueJob(
                new ErpAccountSyncJob(accountIds, attempt + 1)
            );
        }
    }
}
