public without sharing class OpportunityPipelineHandler {
    // These stored totals must include all opportunities, regardless of the
    // initiating user's record visibility. Run this trigger service in system mode.
    public static void handleAfter(
        List<Opportunity> newRecords,
        Map<Id, Opportunity> oldMap
    ) {
        Set<Id> accountIds = new Set<Id>();

        if (newRecords == null) {
            // After delete.
            for (Opportunity oldRecord : oldMap.values()) {
                accountIds.add(oldRecord.AccountId);
            }
        } else {
            // After insert, update, or undelete.
            for (Opportunity newRecord : newRecords) {
                Opportunity oldRecord = oldMap == null
                    ? null
                    : oldMap.get(newRecord.Id);

                // The legacy Account trigger changes only the reporting field.
                // Ignore updates that cannot change either roll-up. Unlike a
                // transaction-wide recursion flag, this permits later real changes
                // to these same opportunities in the same transaction.
                if (
                    oldRecord != null &&
                    newRecord.AccountId == oldRecord.AccountId &&
                    newRecord.Amount == oldRecord.Amount &&
                    newRecord.IsClosed == oldRecord.IsClosed
                ) {
                    continue;
                }

                accountIds.add(newRecord.AccountId);
                if (oldRecord != null) {
                    accountIds.add(oldRecord.AccountId);
                }
            }
        }

        accountIds.remove(null);
        if (!accountIds.isEmpty()) {
            recalculate(accountIds);
        }
    }

    private static void recalculate(Set<Id> accountIds) {
        // Lock parents before calculating to serialize concurrent recalculations
        // affecting the same accounts.
        List<Account> accounts = [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
            FOR UPDATE
        ];

        if (accounts.isEmpty()) {
            return;
        }

        Map<Id, AggregateResult> totalsByAccount =
            new Map<Id, AggregateResult>();

        for (AggregateResult result : [
            SELECT AccountId,
                   SUM(Amount) pipelineAmount,
                   COUNT(Id) openCount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            totalsByAccount.put((Id) result.get('AccountId'), result);
        }

        List<Account> updates = new List<Account>();

        for (Account account : accounts) {
            AggregateResult totals = totalsByAccount.get(account.Id);
            Decimal pipelineAmount = 0;
            Integer openCount = 0;

            if (totals != null) {
                pipelineAmount = (Decimal) totals.get('pipelineAmount');
                openCount = (Integer) totals.get('openCount');

                // SUM ignores null amounts and can return null when all are null.
                if (pipelineAmount == null) {
                    pipelineAmount = 0;
                }
            }

            // Missing aggregate rows deliberately retain zero for both fields.
            // Avoid unnecessary Account DML and its downstream automation.
            if (
                account.FB_Open_Pipeline__c != pipelineAmount ||
                account.FB_Open_Opportunities__c != openCount
            ) {
                updates.add(new Account(
                    Id = account.Id,
                    FB_Open_Pipeline__c = pipelineAmount,
                    FB_Open_Opportunities__c = openCount
                ));
            }
        }

        if (!updates.isEmpty()) {
            // Use atomic DML: a failed roll-up must also fail the originating DML.
            update updates;
        }
    }
}
