/**
 * Purges expired integration logs in batches.
 * Runs in system context without sharing so retention applies to all logs.
 */
public without sharing class LogPurgeJob
    implements Schedulable, Database.Batchable<SObject> {

    public LogPurgeJob() {
    }

    public static Id scheduleNightly() {
        // The schedule uses the scheduling user's time zone.
        return System.schedule(
            'Log purge (nightly)',
            '0 0 2 * * ?',
            new LogPurgeJob()
        );
    }

    public void execute(SchedulableContext context) {
        Database.executeBatch(new LogPurgeJob(), 200);
    }

    public Database.QueryLocator start(Database.BatchableContext context) {
        Datetime runTime = System.now();
        Datetime normalCutoff = runTime.addDays(-30);
        Datetime errorCutoff = runTime.addDays(-180);

        // All candidates must be older than 30 days.
        // ERROR logs must additionally be older than 180 days.
        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :normalCutoff
              AND (
                  Level__c = null
                  OR Level__c != 'ERROR'
                  OR CreatedDate < :errorCutoff
              )
        ]);
    }

    public void execute(
        Database.BatchableContext context,
        List<SObject> scope
    ) {
        // Failed scopes surface as batch errors rather than being silently ignored.
        delete scope;
    }

    public void finish(Database.BatchableContext context) {
    }
}
