                reminder.ActivityDate,
                'The reminder must be due 60 days before the renewal CloseDate.'
            );

            remindedRenewals.add(parent.Name);
        }

        Assert.areEqual(
            registeredByName.keySet(),
            remindedRenewals,
            'Every renewal must have exactly one related reminder.'
        );
    }

