    public override void onValidate(Map<Id, SObject> existingRecords) {
        // Apply the non-negative rule to updates as well as inserts.
        onValidate();

        for (Opportunity record : (List<Opportunity>) Records) {
            Opportunity previous = (Opportunity) existingRecords.get(record.Id);

            if (previous.StageName == 'Closed Won'
                && record.Amount != previous.Amount) {
                error(
                    'Amount cannot change on a won opportunity.',
                    record,
                    Opportunity.Amount
                );
            }
        }
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities((List<Opportunity>) records);
        }
    }
