public with sharing class ContactPhoneCleanup {
    /**
     * Normalizes populated phone numbers and returns the first error for each
     * contact whose update fails.
     *
     * Security addition: queries and DML run in user mode. The update call adds
     * AccessLevel.USER_MODE to enforce the caller's permissions while retaining
     * one bulk update with partial success.
     *
     * The requested character-removal rule preserves every '+', including
     * nonleading ones; it does not enforce a single leading '+'.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failures = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return failures;
        }

        List<Contact> contacts = new List<Contact>();

        for (Contact contact : [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
            WITH USER_MODE
        ]) {
            if (String.isBlank(contact.Phone)) {
                continue;
            }

            contact.Phone = contact.Phone.replaceAll('[^0-9+]', '');
            contacts.add(contact);
        }

        if (contacts.isEmpty()) {
            return failures;
        }

        Database.SaveResult[] results = Database.update(
            contacts,
            false,
            AccessLevel.USER_MODE
        );

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                // Failed SaveResults may not contain an Id. Results retain
                // the same ordering as the input records.
                failures.put(
                    contacts[i].Id,
                    results[i].getErrors()[0].getMessage()
                );
            }
        }

        return failures;
    }
}
