public with sharing class PipelineSummary {
    /**
     * Returns totals for the four managed stages, including both date boundaries.
     * Enforces the caller's record access and object/field permissions.
     * Throws IllegalArgumentException for missing or reversed date boundaries.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        if (fromDate == null || toDate == null) {
            throw new IllegalArgumentException('Both date boundaries are required.');
        }
        if (fromDate > toDate) {
            throw new IllegalArgumentException('fromDate must not be after toDate.');
        }

        Map<String, Decimal> totals = new Map<String, Decimal>{
            'Prospecting' => 0,
            'Qualification' => 0,
            'Proposal/Price Quote' => 0,
            'Negotiation/Review' => 0
        };
        Set<String> stageNames = totals.keySet();

        // Use one grouped query rather than four per-stage queries.
        // Although four is bounded, the SOQL budget is shared by the entire
        // transaction; one query leaves more room for automation and callers.
        for (AggregateResult result : [
            SELECT StageName, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE StageName IN :stageNames
                AND CloseDate >= :fromDate
                AND CloseDate <= :toDate
            WITH USER_MODE
            GROUP BY StageName
        ]) {
            Decimal totalAmount = (Decimal) result.get('totalAmount');

            // SUM ignores null amounts; an all-null group keeps its zero.
            if (totalAmount != null) {
                totals.put((String) result.get('StageName'), totalAmount);
            }
        }

        return totals;
    }
}
