```apex
/**
 * Internal, privileged maintenance service. System mode and without sharing are
 * intentional: the scheduled job must process opportunities across the org.
 * Do not expose this method through an untrusted endpoint without authorization.
 *
 * The list-form SOQL loop bounds memory usage, but each chunk still shares the
 * same transaction limits: 10,000 DML rows, 150 DML statements, and synchronous
 * CPU limits. Triggers and flows also consume those limits.
 *
 * For larger workloads, use Batch Apex and persist/report the completed count
 * from finish(). That requires changing the caller's contract: a synchronous
 * method cannot return the final count from asynchronous processing.
 */
public without sharing class StaleOpportunityCloser {
    public class SynchronousCapacityException extends Exception {}

    /**
     * Closes eligible opportunities and returns the number updated.
     * Throws rather than returning a partial count if any chunk fails.
     */
    public static Integer closeStale(Date cutoff) {
        if (cutoff == null) {
            throw new IllegalArgumentException('cutoff must not be null.');
        }

        Integer closedCount = 0;
        Savepoint checkpoint = null;

        try {
            // FOR UPDATE protects selected records against concurrent edits.
            // Each chunk contains up to 200 records.
            for (List<Opportunity> chunk : [
                SELECT Id, StageName
                FROM Opportunity
                WHERE IsClosed = false
                    AND CloseDate < :cutoff
                WITH SYSTEM_MODE
                FOR UPDATE
            ]) {
                // Reserve statements for this update, a possible rollback,
                // and creation of the savepoint on the first chunk.
                Integer statementsNeeded = (checkpoint == null) ? 3 : 2;

                if (
                    chunk.size() >
                        Limits.getLimitDmlRows() - Limits.getDmlRows() ||
                    statementsNeeded >
                        Limits.getLimitDmlStatements() - Limits.getDmlStatements()
                ) {
                    throw new SynchronousCapacityException(
                        'Insufficient synchronous DML capacity. ' +
                        'Use Batch Apex for this workload.'
                    );
                }

                // Created lazily so an empty result requires no DML statements.
                if (checkpoint == null) {
                    checkpoint = Database.setSavepoint();
                }

                for (Opportunity opportunity : chunk) {
                    opportunity.StageName = 'Closed Lost';
                }

                // All-or-none for this chunk. The savepoint also makes failures
                // atomic across earlier chunks if the caller catches an error.
                update as system chunk;
                closedCount += chunk.size();
            }

            return closedCount;
        } catch (Exception failure) {
            if (checkpoint != null) {
                Database.rollback(checkpoint);
            }
            throw failure;
        } finally {
            if (checkpoint != null) {
                Database.releaseSavepoint(checkpoint);
            }
        }
        // Uncatchable governor-limit failures roll back the entire transaction.
        // The capacity checks cannot predict additional work done by automation.
    }
}
