public with sharing class ErpCustomerSync
    implements Queueable, Database.AllowsCallouts {

    private List<Customer> customers;

    public ErpCustomerSync(List<Account> insertedAccounts) {
        // One trigger invocation supplies at most 200 Accounts.
        // Snapshot only the required fields at creation; no re-query is needed.
        customers = new List<Customer>();

        for (Account accountRecord : insertedAccounts) {
            Customer customer = new Customer();
            // Converting an Apex Id to String produces its 18-character form.
            customer.salesforceId = String.valueOf(accountRecord.Id);
            customer.name = accountRecord.Name;
            customer.country = String.isBlank(accountRecord.BillingCountry)
                ? null
                : accountRecord.BillingCountry;
            customers.add(customer);
        }
    }

    public void execute(QueueableContext context) {
        if (customers.isEmpty()) {
            return;
        }

        HttpRequest request = new HttpRequest();
        request.setEndpoint('callout:ERP/api/customers');
        request.setMethod('POST');
        request.setHeader('Content-Type', 'application/json');
        request.setTimeout(120000);

        // Explicitly retain null fields so blank countries become JSON null.
        request.setBody(JSON.serialize(customers, false));

        // Expected response: 202 Accepted.
        // Error handling and retries are intentionally outside this ticket.
        Http http = new Http();
        http.send(request);
    }

    private class Customer {
        public String salesforceId;
        public String name;
        public String country;
    }
}
