public with sharing class FollowUpTaskService {
    /**
     * Creates one follow-up task per distinct, non-null opportunity Id.
     * Null or empty input produces no tasks and an empty result.
     *
     * Deliberate difference: uses one bulk insert with allOrNone=false rather
     * than an insert inside each iteration. Processing 150-250 opportunities
     * individually risks exceeding the 150-DML-statement governor limit,
     * whose exception cannot be caught. SaveResult reports individual failures
     * without preventing other valid tasks from being created.
     *
     * Queries and inserts run in user mode to enforce sharing, CRUD and FLS.
     * Missing or inaccessible opportunities are reported as failures.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        failedOpportunityIds.addAll(opportunityIds);
        failedOpportunityIds.remove(null);
        if (failedOpportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        List<Opportunity> opportunities;
        try {
            opportunities = [
                SELECT Id, Name, OwnerId
                FROM Opportunity
                WHERE Id IN :failedOpportunityIds
                WITH USER_MODE
            ];
        } catch (QueryException ex) {
            // For example, missing object or field read permission.
            // No tasks have been created, so every requested Id remains failed.
            return failedOpportunityIds;
        }

        Date dueDate = Date.today().addDays(7);
        List<Task> followUps = new List<Task>();

        for (Opportunity opportunity : opportunities) {
            followUps.add(new Task(
                WhatId = opportunity.Id,
                OwnerId = opportunity.OwnerId,
                Subject = 'Follow up: ' + opportunity.Name,
                ActivityDate = dueDate,
                Status = 'Not Started',
                Priority = 'Normal'
            ));
        }

        if (followUps.isEmpty()) {
            return failedOpportunityIds;
        }

        Database.SaveResult[] results;
        try {
            results = Database.insert(
                followUps,
                false,
                AccessLevel.USER_MODE
            );
        } catch (DmlException ex) {
            // A statement-level failure produced no successful results.
            // Ordinary record-level failures are handled through SaveResult.
            return failedOpportunityIds;
        }

        // SaveResult entries correspond to the input records in the same order.
        for (Integer i = 0; i < results.size(); i++) {
            if (results[i].isSuccess()) {
                failedOpportunityIds.remove(followUps[i].WhatId);
            }
        }

        return failedOpportunityIds;
    }
}
