trigger OpportunityTrigger on Opportunity (
    after insert,
    after update,
    after delete,
    after undelete
) {
    /*
     * Deliberately collect Account IDs and dispatch once per trigger invocation.
     * One future call per Opportunity would exceed the 50-call transaction limit
     * for a CPQ batch of 200.
     *
     * Also handle reparenting, deletion, and undelete so neither the old nor
     * the current Account is left with a stale Rating.
     */
    Set<Id> accountIds = new Set<Id>();

    switch on Trigger.operationType {
        when AFTER_INSERT, AFTER_UNDELETE {
            for (Opportunity opp : Trigger.new) {
                accountIds.add(opp.AccountId);
            }
        }
        when AFTER_UPDATE {
            for (Opportunity opp : Trigger.new) {
                Opportunity oldOpp = Trigger.oldMap.get(opp.Id);

                if (opp.StageName != oldOpp.StageName ||
                    opp.Amount != oldOpp.Amount ||
                    opp.AccountId != oldOpp.AccountId) {
                    accountIds.add(opp.AccountId);
                    accountIds.add(oldOpp.AccountId);
                }
            }
        }
        when AFTER_DELETE {
            for (Opportunity opp : Trigger.old) {
                accountIds.add(opp.AccountId);
            }
        }
    }

    accountIds.remove(null);

    if (!accountIds.isEmpty()) {
        AccountRatingService.recalculate(accountIds);
    }
}
