/*
 * Trusted trigger automation intentionally runs without sharing:
 * Rating must reflect the complete pipeline, not just Opportunities visible
 * to the user who initiated the save.
 */
public without sharing class AccountRatingService {
    private static final Decimal HOT_THRESHOLD = 100000;

    /*
     * The entry point accepts a collection instead of one Account ID.
     * Ordinary saves enqueue one bulk future job per trigger invocation.
     *
     * Future and Batch Apex cannot invoke future methods. In those contexts,
     * calculate inline within the already-asynchronous transaction instead.
     */
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Set<Id> cleanIds = new Set<Id>(accountIds);
        cleanIds.remove(null);

        if (cleanIds.isEmpty()) {
            return;
        }

        if (System.isFuture() || System.isBatch()) {
            applyRatings(cleanIds);
        } else {
            recalculateAsync(cleanIds);
        }
    }

    @future
    private static void recalculateAsync(Set<Id> accountIds) {
        applyRatings(accountIds);
    }

    private static void applyRatings(Set<Id> accountIds) {
        /*
         * Lock before reading the pipeline so overlapping workers for the
         * same Accounts cannot overwrite each other's newer calculations.
         * Accounts deleted before the job executes are naturally excluded.
         */
        Map<Id, Account> lockedAccounts = new Map<Id, Account>([
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :accountIds
            FOR UPDATE
        ]);

        if (lockedAccounts.isEmpty()) {
            return;
        }

        Set<Id> existingAccountIds = lockedAccounts.keySet();
        Set<Id> accountsWithOpenPipeline = new Set<Id>();
        Set<Id> accountsWithHotPipeline = new Set<Id>();

        /*
         * Semi-joins retrieve only matching Account IDs, rather than loading
         * every open Opportunity. Returned rows remain bounded by the number
         * of affected Accounts even when those Accounts have large pipelines.
         *
         * Read current data at execution time; future jobs need not run in
         * the order in which Opportunity transactions submitted them.
         */
        for (Account accountRecord : [
            SELECT Id
            FROM Account
            WHERE Id IN :existingAccountIds
                AND Id IN (
                    SELECT AccountId
                    FROM Opportunity
                    WHERE AccountId IN :existingAccountIds
                        AND IsClosed = false
                )
        ]) {
            accountsWithOpenPipeline.add(accountRecord.Id);
        }

        for (Account accountRecord : [
            SELECT Id
            FROM Account
            WHERE Id IN :existingAccountIds
                AND Id IN (
                    SELECT AccountId
                    FROM Opportunity
                    WHERE AccountId IN :existingAccountIds
                        AND IsClosed = false
                        AND Amount >= :HOT_THRESHOLD
                )
        ]) {
            accountsWithHotPipeline.add(accountRecord.Id);
        }

        List<Account> updates = new List<Account>();

        for (Account accountRecord : lockedAccounts.values()) {
            String desiredRating = 'Cold';

            if (accountsWithHotPipeline.contains(accountRecord.Id)) {
                desiredRating = 'Hot';
            } else if (accountsWithOpenPipeline.contains(accountRecord.Id)) {
                desiredRating = 'Warm';
            }

            // Avoid unnecessary DML and downstream Account automation.
            if (accountRecord.Rating != desiredRating) {
                updates.add(new Account(
                    Id = accountRecord.Id,
                    Rating = desiredRating
                ));
            }
        }

        if (!updates.isEmpty()) {
            // Do not silently ignore failures; let the async job report them.
            update updates;
        }
    }
}
