public with sharing class LeadContactMatcher {
    /**
     * Returns one contact Id (or null) per lead, preserving lead order.
     *
     * Indexing contacts avoids up to 9,000,000 nested-loop comparisons inside
     * the import transaction, where Apex CPU limits are shared. This takes
     * O(leads + contacts) time and O(unique contact emails) auxiliary space.
     *
     * Null lists are treated as empty. Null entries never match.
     * No queries, DML, or changes to the supplied records are performed.
     */
    public static List<Id> matchByEmail(
        List<Lead> leads,
        List<Contact> contacts
    ) {
        List<Id> matches = new List<Id>();
        if (leads == null || leads.isEmpty()) {
            return matches;
        }

        Map<String, Id> firstContactIdByEmail = new Map<String, Id>();

        if (contacts != null) {
            for (Contact candidate : contacts) {
                if (candidate == null) {
                    continue;
                }

                String emailKey = normalizeEmail(candidate.Email);
                if (emailKey != null &&
                    !firstContactIdByEmail.containsKey(emailKey)) {
                    // Preserve the first contact, even if its Id is null.
                    firstContactIdByEmail.put(emailKey, candidate.Id);
                }
            }
        }

        for (Lead sourceLead : leads) {
            String emailKey = sourceLead == null
                ? null
                : normalizeEmail(sourceLead.Email);

            matches.add(
                emailKey == null ? null : firstContactIdByEmail.get(emailKey)
            );
        }

        return matches;
    }

    private static String normalizeEmail(String email) {
        return String.isBlank(email) ? null : email.trim().toLowerCase();
    }
}
