trigger CaseTrigger on Case (after update) {
    Set<Id> caseIds = new Set<Id>();

    for (Case c : Trigger.new) {
        Case previous = Trigger.oldMap.get(c.Id);

        if (!previous.IsClosed && c.IsClosed && c.ContactId != null) {
            caseIds.add(c.Id);
        }
    }

    /*
     * Changed from one enqueue per Case to one enqueue for this trigger batch.
     * Salesforce permits at most 50 Queueable enqueues per synchronous
     * transaction and one per asynchronous transaction. Enqueuing separately
     * for 200 Cases would fail and roll back the closing transaction.
     *
     * The job uses partial-success DML to isolate record-level Task errors.
     * This replaces, rather than preserves, separate-transaction isolation:
     * an unhandled exception or governor-limit failure can still fail the job.
     */
    if (!caseIds.isEmpty()) {
        System.enqueueJob(new CaseSurveyJob(caseIds));
    }
}
