/**
 * Internal, record-scoped automation invoked by CaseTrigger.
 *
 * System context is intentional: follow-up creation must not depend on the
 * closing agent's Task permissions or continued sharing access to a Case.
 * This class does not expose a UI or remote entry point.
 *
 * AllowsCallouts supports the planned integration. Future callouts must run
 * before DML and be bulked or chunked to respect callout limits.
 */
public without sharing class CaseSurveyJob
    implements Queueable, Database.AllowsCallouts {

    private Set<Id> caseIds;

    public CaseSurveyJob(Set<Id> caseIds) {
        this.caseIds = new Set<Id>();

        if (caseIds != null) {
            this.caseIds.addAll(caseIds);
            this.caseIds.remove(null);
        }
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        Date dueDate = Date.today().addDays(2);
        List<Task> tasks = new List<Task>();

        /*
         * Re-query to obtain the current contact and skip deleted Cases or
         * Cases whose contact has been removed.
         *
         * Do not filter on current IsClosed: the trigger already captured
         * the close transition, even if a Case subsequently reopens.
         */
        for (Case c : [
            SELECT Id, ContactId, CaseNumber
            FROM Case
            WHERE Id IN :caseIds
                AND ContactId != null
        ]) {
            tasks.add(new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = dueDate,
                Status = 'Not Started'
            ));
        }

        if (tasks.isEmpty()) {
            return;
        }

        // Ordinary record-level errors must not roll back successful Tasks.
        Database.SaveResult[] results = Database.insert(tasks, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                for (Database.Error error : results[i].getErrors()) {
                    // Diagnostic logging only; this does not schedule a retry.
                    // Do not throw here and undo the successful inserts.
                    System.debug(
                        LoggingLevel.ERROR,
                        'CaseSurveyJob ' + context.getJobId()
                        + ': Task creation failed for Case '
                        + tasks[i].WhatId
                        + '. ' + error.getStatusCode()
                        + ': ' + error.getMessage()
                    );
                }
            }
        }
    }
}
