public with sharing class RenewalReminderService {
    /**
     * Sends one renewal reminder per distinct, accessible opportunity.
     * Null input, null IDs, and missing or inaccessible records are ignored.
     * Object- and field-level permission errors propagate to the caller.
     *
     * Deliberately does NOT call Messaging.sendEmail inside the loop:
     * Apex permits only 10 sendEmail invocations per transaction. Sending
     * separately for up to 200 opportunities would cause an uncatchable
     * governor-limit exception and roll back the transaction.
     *
     * One bulk call with allOrNone=false allows valid messages to succeed
     * despite individual message failures. It does not protect against
     * transaction-wide errors or exhausted platform limits.
     *
     * Targeting owner User IDs avoids the daily external-email allocation,
     * but does not bypass the Apex sendEmail invocation limit.
     *
     * Returns the number of messages Salesforce accepted for sending.
     * Delivery is not guaranteed, and sending depends on transaction commit.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> uniqueIds = new Set<Id>(opportunityIds);
        uniqueIds.remove(null);
        if (uniqueIds.isEmpty()) {
            return 0;
        }

        List<Messaging.SingleEmailMessage> messages =
            new List<Messaging.SingleEmailMessage>();

        for (Opportunity opportunity : [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :uniqueIds
            WITH USER_MODE
        ]) {
            Messaging.SingleEmailMessage message =
                new Messaging.SingleEmailMessage();

            message.setTargetObjectId(opportunity.OwnerId);
            message.setSaveAsActivity(false);
            message.setSubject('Renewal due: ' + opportunity.Name);
            message.setPlainTextBody(
                'The renewal for opportunity "' + opportunity.Name +
                '" is due.\nClose date: ' +
                String.valueOf(opportunity.CloseDate) +
                '.\nPlease review this opportunity.'
            );

            messages.add(message);
        }

        if (messages.isEmpty()) {
            return 0;
        }

        Messaging.SendEmailResult[] results =
            Messaging.sendEmail(messages, false);

        Integer successfulCount = 0;
        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                successfulCount++;
            }
        }

        return successfulCount;
    }
}
