```apex
/**
 * Synchronizes contacts when their account's BillingCountry changes.
 *
 * Deliberate change to the proposed approach:
 * Loading all 2.3 million contacts would exceed synchronous SOQL-row and heap
 * limits. Instead, identify changed accounts first, then issue one query
 * restricted to their contacts. No query runs when no countries changed.
 *
 * This is synchronous, atomic automation. A 200-account batch does not bound
 * contact fan-out: queried contacts and updated records must still fit the
 * transaction's remaining limits (50,000 SOQL rows and 10,000 DML rows overall,
 * plus heap and CPU limits). If that cannot be guaranteed, reduce integration
 * batch sizes; individual high-fan-out accounts require a separately designed
 * Batch Apex synchronization flow.
 *
 * Intentionally without sharing: this internal trigger automation must
 * synchronize eligible contacts regardless of the initiating user's record
 * visibility. It exposes no client-callable entry point or queried data.
 */
public without sharing class AccountCountrySync {
    public static void afterUpdate(
        List<Account> updatedAccounts,
        Map<Id, Account> previousAccountsById
    ) {
        Map<Id, String> newCountriesByAccountId = new Map<Id, String>();

        for (Account accountRecord : updatedAccounts) {
            Account previousAccount =
                previousAccountsById.get(accountRecord.Id);

            if (accountRecord.BillingCountry != previousAccount.BillingCountry) {
                // Retain the account ID even when the new country is null.
                newCountriesByAccountId.put(
                    accountRecord.Id,
                    accountRecord.BillingCountry
                );
            }
        }

        if (newCountriesByAccountId.isEmpty()) {
            return;
        }

        Set<Id> changedAccountIds = newCountriesByAccountId.keySet();
        List<Contact> contactsToUpdate = new List<Contact>();

        // A SOQL-for loop executes one query and streams its results.
        // There is no per-account or per-contact query.
        for (Contact contactRecord : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ]) {
            String previousCountry =
                previousAccountsById.get(contactRecord.AccountId).BillingCountry;
            String newCountry =
                newCountriesByAccountId.get(contactRecord.AccountId);

            Boolean followsAccount =
                String.isBlank(contactRecord.MailingCountry) ||
                contactRecord.MailingCountry == previousCountry;

            if (followsAccount && contactRecord.MailingCountry != newCountry) {
                // Write only the requested field; null clears the country.
                contactsToUpdate.add(new Contact(
                    Id = contactRecord.Id,
                    MailingCountry = newCountry
                ));
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            // One all-or-none DML operation. Failures propagate so an account
            // update cannot silently succeed with an incomplete contact sync.
            update contactsToUpdate;
        }
    }
}
