import { LightningElement, api } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    @api recordId;

    opportunities = [];
    isLoading = false;
    hasError = false;
    errorMessage = '';
    _initialized = false;

    connectedCallback() {
        // connectedCallback can run again if the component is reinserted.
        if (!this._initialized) {
            this._initialized = true;
            this.loadOpportunities();
        }
    }

    get hasOpportunities() {
        return this.opportunities.length > 0;
    }

    handleRetry() {
        this.loadOpportunities();
    }

    async loadOpportunities() {
        if (this.isLoading) {
            return;
        }

        this.isLoading = true;
        this.hasError = false;
        this.errorMessage = '';

        try {
            const opportunities = await getOpenOpportunities({
                accountId: this.recordId
            });
            this.opportunities = opportunities ?? [];
        } catch (error) {
            this.hasError = true;
            this.errorMessage =
                error?.body?.message ??
                error?.message ??
                'Unable to load open opportunities.';
        } finally {
            this.isLoading = false;
        }
    }
}
