import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    hasStats = false;
    errorMessage = '';

    _connected = false;
    _connectionVersion = 0;
    _intervalId;
    _requestInFlight = false;

    connectedCallback() {
        if (this._connected) {
            return;
        }

        this._connected = true;
        this._connectionVersion += 1;

        document.addEventListener(
            'visibilitychange',
            this._handleVisibilityChange
        );
        this._handleVisibilityChange();
    }

    disconnectedCallback() {
        this._connected = false;
        this._connectionVersion += 1;
        this._stopPolling();

        document.removeEventListener(
            'visibilitychange',
            this._handleVisibilityChange
        );

        // Apex requests cannot be canceled. Retain the in-flight lock until
        // settlement, including if this instance reconnects before then.
    }

    _handleVisibilityChange = () => {
        this._stopPolling();

        if (!this._connected || document.visibilityState === 'hidden') {
            return;
        }

        this._refreshStats();
        this._intervalId = setInterval(() => {
            this._refreshStats();
        }, REFRESH_INTERVAL_MS);
    };

    _stopPolling() {
        if (this._intervalId !== undefined) {
            clearInterval(this._intervalId);
            this._intervalId = undefined;
        }
    }

    async _refreshStats() {
        if (
            !this._connected ||
            document.visibilityState === 'hidden' ||
            this._requestInFlight
        ) {
            return;
        }

        this._requestInFlight = true;
        const connectionVersion = this._connectionVersion;

        try {
            const stats = await getQueueStats();

            // Ignore results belonging to an earlier attachment.
            if (
                !this._connected ||
                connectionVersion !== this._connectionVersion
            ) {
                return;
            }

            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.hasStats = true;
            this.errorMessage = '';
        } catch (error) {
            if (
                this._connected &&
                connectionVersion === this._connectionVersion
            ) {
                this.errorMessage =
                    error?.body?.message ||
                    error?.message ||
                    'Unable to load queue statistics.';
            }
        } finally {
            this._requestInFlight = false;
        }
    }
}
