import { LightningElement, api } from 'lwc';

const HANDLED_KEYS = new Set([
    'ArrowDown',
    'ArrowUp',
    'Home',
    'End',
    'Enter',
    ' '
]);

export default class StatusListbox extends LightningElement {
    @api label = '';

    _options = [];
    _value;
    _activeIndex = -1;

    @api
    get options() {
        return this._options;
    }

    set options(options) {
        this._options = Array.isArray(options)
            ? options.map(({ value, label }) => ({ value, label }))
            : [];
        this.synchronizeActiveOption();
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value;
        this.synchronizeActiveOption();
    }

    get renderedOptions() {
        const selectedIndex = this._options.findIndex(
            (option) => option.value === this._value
        );

        return this._options.map((option, index) => ({
            value: option.value,
            label: option.label,
            index,
            id: `status-option-${index}`,
            ariaSelected: index === selectedIndex ? 'true' : 'false'
        }));
    }

    get activeOptionId() {
        // LWC scopes IDs and same-template ARIA ID references together.
        return this._activeIndex >= 0
            ? `status-option-${this._activeIndex}`
            : undefined;
    }

    synchronizeActiveOption() {
        const selectedIndex = this._options.findIndex(
            (option) => option.value === this._value
        );

        if (selectedIndex >= 0) {
            this._activeIndex = selectedIndex;
        } else {
            this._activeIndex = this._options.length > 0 ? 0 : -1;
        }
    }

    handleKeyDown(event) {
        if (!HANDLED_KEYS.has(event.key)) {
            return;
        }

        event.preventDefault();

        if (this._options.length === 0) {
            return;
        }

        const lastIndex = this._options.length - 1;

        switch (event.key) {
            case 'ArrowDown':
                this._activeIndex = Math.min(this._activeIndex + 1, lastIndex);
                break;
            case 'ArrowUp':
                this._activeIndex = Math.max(this._activeIndex - 1, 0);
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = lastIndex;
                break;
            case 'Enter':
            case ' ':
                this.selectOption(this._activeIndex);
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const index = Number(event.currentTarget.dataset.index);

        // Options never receive DOM focus.
        this.refs.listbox.focus();
        this.selectOption(index);
    }

    selectOption(index) {
        if (
            !Number.isInteger(index) ||
            index < 0 ||
            index >= this._options.length
        ) {
            return;
        }

        this._activeIndex = index;
        const value = this._options[index].value;

        if (value === this._value) {
            return;
        }

        this._value = value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value }
            })
        );
    }
}
