public with sharing class EmployerService {
    public class EmployerServiceException extends Exception {}

    /**
     * Sets employers through NPSP's primary-affiliation automation.
     *
     * Account IDs must identify existing Organization accounts.
     * This method performs at most one SOQL query and one DML statement;
     * work performed by NPSP automation is additional.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Null values are not interpreted as requests to remove an employer.
        for (Id contactId : employerByContactId.keySet()) {
            Id organizationId = employerByContactId.get(contactId);

            if (contactId == null ||
                contactId.getSObjectType() != Contact.SObjectType) {
                throw new EmployerServiceException(
                    'Each employer assignment must have a valid Contact ID.'
                );
            }

            if (organizationId == null ||
                organizationId.getSObjectType() != Account.SObjectType) {
                throw new EmployerServiceException(
                    'Each employer assignment must have an Organization Account ID.'
                );
            }
        }

        List<Contact> contacts = [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :employerByContactId.keySet()
            WITH USER_MODE
        ];

        // Do not silently succeed after processing only part of the request.
        if (contacts.size() != employerByContactId.size()) {
            throw new EmployerServiceException(
                'One or more contacts do not exist or are not accessible.'
            );
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact existingContact : contacts) {
            Id organizationId = employerByContactId.get(existingContact.Id);

            if (existingContact.npsp__Primary_Affiliation__c != organizationId) {
                contactsToUpdate.add(new Contact(
                    Id = existingContact.Id,
                    npsp__Primary_Affiliation__c = organizationId
                ));
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            // NPSP creates/reuses the Current, primary affiliation and makes
            // the previous primary affiliation Former, non-primary, and ended
            // today. Do not write affiliations directly or change AccountId:
            // the contact must remain in its household.
            //
            // User-mode DML enforces access and is all-or-none.
            update as user contactsToUpdate;
        }
    }
}
