public with sharing class SoftCreditService {
    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(
        List<SoftCreditRequest> requests
    ) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        Set<String> requestedPairs = new Set<String>();
        Map<Id, Set<Id>> contactsByOpportunity = new Map<Id, Set<Id>>();

        for (SoftCreditRequest request : requests) {
            if (
                request == null ||
                request.opportunityId == null ||
                request.contactId == null
            ) {
                throw new SoftCreditException(
                    'Every request must identify an opportunity and a contact.'
                );
            }

            if (
                request.opportunityId.getSObjectType() != Opportunity.SObjectType ||
                request.contactId.getSObjectType() != Contact.SObjectType
            ) {
                throw new SoftCreditException(
                    'A request contains an incorrect record ID type.'
                );
            }

            if (request.amount == null || request.amount <= 0) {
                throw new SoftCreditException(
                    'Every partial soft credit amount must be positive.'
                );
            }

            String key = pairKey(request.opportunityId, request.contactId);
            if (!requestedPairs.add(key)) {
                throw new SoftCreditException(
                    'An opportunity/contact pair occurs more than once.'
                );
            }

            opportunityIds.add(request.opportunityId);
            contactIds.add(request.contactId);

            if (!contactsByOpportunity.containsKey(request.opportunityId)) {
                contactsByOpportunity.put(
                    request.opportunityId,
                    new Set<Id>()
                );
            }
            contactsByOpportunity.get(request.opportunityId).add(
                request.contactId
            );
        }

        // Query 1. Validate every opportunity and amount before any DML.
        Map<Id, Opportunity> opportunities = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :opportunityIds
            WITH USER_MODE
        ]);

        for (SoftCreditRequest request : requests) {
            Opportunity opportunity = opportunities.get(request.opportunityId);

            if (opportunity == null) {
                throw new SoftCreditException(
                    'An opportunity does not exist or is not accessible: ' +
                    request.opportunityId
                );
            }

            if (opportunity.npsp__Primary_Contact__c == request.contactId) {
                throw new SoftCreditException(
                    'An opportunity primary contact cannot receive a partial ' +
                    'soft credit on that opportunity.'
                );
            }

            if (
                opportunity.Amount == null ||
                request.amount > opportunity.Amount
            ) {
                throw new SoftCreditException(
                    'A partial soft credit amount cannot exceed the ' +
                    'opportunity amount.'
                );
            }
        }

        // Query 2. Also obtain the display names for writable Contact Name fields.
        Map<Id, Contact> contacts = new Map<Id, Contact>([
            SELECT Id, Name
            FROM Contact
            WHERE Id IN :contactIds
            WITH USER_MODE
        ]);

        for (Id contactId : contactIds) {
            if (!contacts.containsKey(contactId)) {
                throw new SoftCreditException(
                    'A contact does not exist or is not accessible: ' +
                    contactId
                );
            }
        }

        // Exact-pair predicates avoid fetching the Cartesian product of all
        // requested opportunities and contacts.
        Map<String, Object> roleBinds = new Map<String, Object>();
        String rolePredicate = buildPairPredicate(
            'OpportunityId',
            'ContactId',
            contactsByOpportunity,
            roleBinds
        );

        // Query 3. Prefer a primary role as the fallback keeper, without
        // changing any existing IsPrimary flags.
        List<OpportunityContactRole> existingRoles =
            Database.queryWithBinds(
                'SELECT Id, OpportunityId, ContactId, Role, IsPrimary ' +
                'FROM OpportunityContactRole WHERE ' + rolePredicate +
                ' ORDER BY IsPrimary DESC, Id',
                roleBinds,
                AccessLevel.USER_MODE
            );

        Map<String, List<OpportunityContactRole>> rolesByPair =
            new Map<String, List<OpportunityContactRole>>();

        for (OpportunityContactRole contactRole : existingRoles) {
            String key = pairKey(
                contactRole.OpportunityId,
                contactRole.ContactId
            );

            if (!rolesByPair.containsKey(key)) {
                rolesByPair.put(key, new List<OpportunityContactRole>());
            }
            rolesByPair.get(key).add(contactRole);
        }

        Map<String, Object> creditBinds = new Map<String, Object>();
        String creditPredicate = buildPairPredicate(
            'npsp__Opportunity__c',
            'npsp__Contact__c',
            contactsByOpportunity,
            creditBinds
        );

        // Query 4.
        List<npsp__Partial_Soft_Credit__c> existingCredits =
            Database.queryWithBinds(
                'SELECT Id, npsp__Opportunity__c, npsp__Contact__c, ' +
                'npsp__Contact_Role_ID__c ' +
                'FROM npsp__Partial_Soft_Credit__c WHERE ' +
                creditPredicate,
                creditBinds,
                AccessLevel.USER_MODE
            );

        Map<String, npsp__Partial_Soft_Credit__c> creditsByPair =
            new Map<String, npsp__Partial_Soft_Credit__c>();

        for (npsp__Partial_Soft_Credit__c credit : existingCredits) {
            String key = pairKey(
                credit.npsp__Opportunity__c,
                credit.npsp__Contact__c
            );

            // Do not silently choose between conflicting historical credits.
            // This data-integrity check also occurs before any DML.
            if (creditsByPair.containsKey(key)) {
                throw new SoftCreditException(
                    'Multiple partial soft credits already exist for pair ' +
                    key + '. Resolve the duplicate credits before retrying.'
                );
            }
            creditsByPair.put(key, credit);
        }

        Map<String, OpportunityContactRole> keeperByPair =
            new Map<String, OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpsert =
            new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete =
            new List<OpportunityContactRole>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(request.opportunityId, request.contactId);
            List<OpportunityContactRole> candidates = rolesByPair.get(key);
            npsp__Partial_Soft_Credit__c existingCredit =
                creditsByPair.get(key);
            OpportunityContactRole keeper;

            if (candidates == null || candidates.isEmpty()) {
                keeper = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = request.role,
                    IsPrimary = false
                );
                rolesToUpsert.add(keeper);
            } else {
                keeper = candidates[0];

                // Preserve the OCR already referenced by the existing credit
                // whenever that reference is valid for this pair.
                if (existingCredit != null) {
                    for (OpportunityContactRole candidate : candidates) {
                        if (
                            referencesRole(
                                existingCredit.npsp__Contact_Role_ID__c,
                                candidate.Id
                            )
                        ) {
                            keeper = candidate;
                            break;
                        }
                    }
                }

                for (OpportunityContactRole candidate : candidates) {
                    if (candidate.Id != keeper.Id) {
                        rolesToDelete.add(
                            new OpportunityContactRole(Id = candidate.Id)
                        );
                    }
                }

                // Use a sparse update: do not overwrite IsPrimary or lookups.
                keeper = new OpportunityContactRole(
                    Id = keeper.Id,
                    Role = request.role
                );
                rolesToUpsert.add(keeper);
            }

            keeperByPair.put(key, keeper);
        }

        // DML 1. Upsert assigns IDs to new OCRs in the same instances retained
        // in keeperByPair. Existing household roles are updated, not duplicated.
        if (!rolesToUpsert.isEmpty()) {
            upsert as user rolesToUpsert;
        }

        Schema.DescribeFieldResult contactNameDescription =
            npsp__Partial_Soft_Credit__c.npsp__Contact_Name__c.getDescribe();
        Boolean writeContactName =
            !contactNameDescription.isCalculated() &&
            !contactNameDescription.isAutoNumber();

        List<npsp__Partial_Soft_Credit__c> creditsToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(request.opportunityId, request.contactId);
            npsp__Partial_Soft_Credit__c existingCredit =
                creditsByPair.get(key);
            npsp__Partial_Soft_Credit__c credit =
                new npsp__Partial_Soft_Credit__c();

            if (existingCredit == null) {
                credit.npsp__Opportunity__c = request.opportunityId;
                credit.npsp__Contact__c = request.contactId;
            } else {
                credit.Id = existingCredit.Id;
            }

            credit.npsp__Amount__c = request.amount;
            credit.npsp__Role_Name__c = request.role;
            credit.npsp__Contact_Role_ID__c =
                String.valueOf(keeperByPair.get(key).Id);

            // Formula display fields are left to Salesforce. For stored text
            // fields, user-mode DML still enforces the caller's field access.
            if (writeContactName) {
                credit.put(
                    'npsp__Contact_Name__c',
                    contacts.get(request.contactId).Name
                );
            }

            creditsToUpsert.add(credit);
        }

        // DML 2. Existing credits have IDs, so their amounts and roles update.
        upsert as user creditsToUpsert;

        // DML 3. Reconcile historical duplicate OCRs only after the partial
        // credits reference their surviving OCRs.
        if (!rolesToDelete.isEmpty()) {
            delete as user rolesToDelete;
        }
    }

    private static String pairKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + ':' + String.valueOf(contactId);
    }

    private static Boolean referencesRole(String storedId, Id roleId) {
        if (String.isBlank(storedId)) {
            return false;
        }

        try {
            // Normalize valid 15-character and 18-character stored IDs.
            return ((Id) storedId) == roleId;
        } catch (StringException invalidId) {
            // A stale or malformed text reference is repaired by the upsert.
            return false;
        }
    }

    private static String buildPairPredicate(
        String opportunityField,
        String contactField,
        Map<Id, Set<Id>> contactsByOpportunity,
        Map<String, Object> binds
    ) {
        List<String> clauses = new List<String>();
        Integer index = 0;

        // Field names are supplied only by the fixed internal call sites.
        // All record identifiers remain bind variables.
        for (Id opportunityId : contactsByOpportunity.keySet()) {
            String opportunityBind = 'opportunity' + index;
            String contactsBind = 'contacts' + index;

            binds.put(opportunityBind, opportunityId);
            binds.put(
                contactsBind,
                contactsByOpportunity.get(opportunityId)
            );

            clauses.add(
                '(' + opportunityField + ' = :' + opportunityBind +
                ' AND ' + contactField + ' IN :' + contactsBind + ')'
            );
            index++;
        }

        return '(' + String.join(clauses, ' OR ') + ')';
    }
}
