/**
 * Creates child-to-parent relationships and lets NPSP create the reciprocals.
 *
 * Existence checks intentionally ignore sharing so hidden relationships are
 * not duplicated. No queried data is returned. Inserts use user mode to enforce
 * the caller's CRUD, field permissions, and record access.
 */
public without sharing class FamilyService {
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> childIds = new Set<Id>();
        Set<Id> parentIds = new Set<Id>();
        Map<String, npe4__Relationship__c> candidatesByPair =
            new Map<String, npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            // Ignore incomplete pairs and self-relationships.
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            String key = pairKey(childId, parentId);

            // Do not submit the same unordered pair twice in this batch.
            if (candidatesByPair.containsKey(key)) {
                continue;
            }

            childIds.add(childId);
            parentIds.add(parentId);

            candidatesByPair.put(
                key,
                new npe4__Relationship__c(
                    npe4__Contact__c = childId,
                    npe4__RelatedContact__c = parentId,
                    npe4__Type__c = 'Parent',
                    npe4__Status__c = 'Current'
                )
            );
        }

        if (candidatesByPair.isEmpty()) {
            return;
        }

        // Any existing type or status, in either direction, blocks this pair.
        for (npe4__Relationship__c existing : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE
                (
                    npe4__Contact__c IN :childIds
                    AND npe4__RelatedContact__c IN :parentIds
                )
                OR
                (
                    npe4__Contact__c IN :parentIds
                    AND npe4__RelatedContact__c IN :childIds
                )
        ]) {
            candidatesByPair.remove(
                pairKey(
                    existing.npe4__Contact__c,
                    existing.npe4__RelatedContact__c
                )
            );
        }

        if (!candidatesByPair.isEmpty()) {
            List<npe4__Relationship__c> relationshipsToInsert =
                candidatesByPair.values();

            // Leave ReciprocalRelationship blank. NPSP creates and links the
            // reverse record, using its List Setting lookup and child gender
            // to select Son, Daughter, or Child. Do not insert it ourselves.
            insert as user relationshipsToInsert;
        }
    }

    private static String pairKey(Id firstId, Id secondId) {
        String first = String.valueOf(firstId);
        String second = String.valueOf(secondId);

        return first.compareTo(second) <= 0
            ? first + ':' + second
            : second + ':' + first;
    }
}
