global with sharing class OPP_MajorGiftFollowUp_TDTM
    extends npsp.TDTM_Runnable {

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper result =
            new npsp.TDTM_Runnable.DmlWrapper();

        if (
            newlist == null ||
            newlist.isEmpty() ||
            (
                triggerAction != npsp.TDTM_Runnable.Action.AfterInsert &&
                triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate
            )
        ) {
            return result;
        }

        Map<Id, Opportunity> previousById = new Map<Id, Opportunity>();

        if (
            triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate &&
            oldlist != null
        ) {
            for (SObject oldRecord : oldlist) {
                Opportunity previous = (Opportunity) oldRecord;
                previousById.put(previous.Id, previous);
            }
        }

        for (SObject newRecord : newlist) {
            Opportunity current = (Opportunity) newRecord;

            // Act only on entry into the qualifying state.
            if (
                !qualifies(current) ||
                qualifies(previousById.get(current.Id))
            ) {
                continue;
            }

            result.objectsToInsert.add(new Task(
                Subject = 'Major gift thank-you call',
                Priority = 'High',
                Status = 'Not Started',
                WhatId = current.Id,
                WhoId = current.npsp__Primary_Contact__c,
                OwnerId = current.OwnerId,
                ActivityDate = current.CloseDate.addDays(3)
            ));
        }

        // Let TDTM perform bulk DML; this handler issues no SOQL or DML.
        return result;
    }

    private static Boolean qualifies(Opportunity gift) {
        return gift != null &&
            gift.StageName == 'Closed Won' &&
            gift.Amount != null &&
            gift.Amount >= 5000;
    }
}
