public with sharing class RecordAccessService {
    // UserRecordAccess accepts at most 200 record IDs per query.
    private static final Integer QUERY_BATCH_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editableRecordIds = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return editableRecordIds;
        }

        Id runningUserId = UserInfo.getUserId();
        List<Id> batch = new List<Id>();

        // Batch by count rather than object type: at most 10 queries
        // for 2,000 IDs, including mixed-object inputs.
        for (Id recordId : recordIds) {
            if (recordId == null) {
                continue;
            }

            batch.add(recordId);
            if (batch.size() == QUERY_BATCH_SIZE) {
                collectEditableIds(batch, runningUserId, editableRecordIds);
                batch.clear();
            }
        }

        if (!batch.isEmpty()) {
            collectEditableIds(batch, runningUserId, editableRecordIds);
        }

        return editableRecordIds;
    }

    private static void collectEditableIds(
        List<Id> batch,
        Id runningUserId,
        Set<Id> editableRecordIds
    ) {
        for (UserRecordAccess recordAccess : [
            SELECT RecordId, HasEditAccess
            FROM UserRecordAccess
            WHERE UserId = :runningUserId
                AND RecordId IN :batch
        ]) {
