public with sharing class EmployeeDirectoryService {
    public static List<FB_Employee__c> getDirectory() {
        if (!FB_Employee__c.SObjectType.getDescribe().isAccessible()) {
            return new List<FB_Employee__c>();
        }

        List<String> selectedFields = new List<String>{ 'Id', 'Name' };
        List<Schema.SObjectField> optionalFields = new List<Schema.SObjectField>{
            FB_Employee__c.Department__c,
            FB_Employee__c.Salary__c,
            FB_Employee__c.Personal_Email__c
        };

        // Omit unreadable fields from the query entirely, rather than nulling them.
        for (Schema.SObjectField fieldToken : optionalFields) {
            Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
            if (fieldDescribe.isAccessible()) {
                selectedFields.add(fieldDescribe.getName());
            }
        }

        String soql =
            'SELECT ' + String.join(selectedFields, ', ') +
            ' FROM FB_Employee__c ORDER BY Name ASC';

        return (List<FB_Employee__c>) Database.query(
            soql,
            AccessLevel.USER_MODE
        );
    }
}
