```apex
/**
 * Maintains the account's open-case count from the current database state.
 *
 * Intentionally runs without sharing in trigger system context: totals must
 * include all related cases, regardless of the initiating user's visibility
 * or field permissions.
 */
public without sharing class TA_Case_RollupOpenCount
    implements TriggerAction.AfterInsert,
        TriggerAction.AfterUpdate,
        TriggerAction.AfterDelete,
        TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        recalculate(collectAccountIds(triggerNew));
    }

    public void afterUpdate(
        List<SObject> triggerNew,
        List<SObject> triggerOld
    ) {
        Set<Id> accountIds = collectAccountIds(triggerNew);
        accountIds.addAll(collectAccountIds(triggerOld));
        recalculate(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        recalculate(collectAccountIds(triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        recalculate(collectAccountIds(triggerNew));
    }

    private static Set<Id> collectAccountIds(List<SObject> records) {
        Set<Id> accountIds = new Set<Id>();

        for (SObject record : records) {
            Id accountId = ((Case) record).AccountId;
            if (accountId != null) {
                accountIds.add(accountId);
            }
        }

        return accountIds;
    }

    private static void recalculate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // Lock parents before counting to serialize competing rollups.
        // Querying existing parents also avoids updating deleted accounts.
        Map<Id, Account> lockedAccounts = new Map<Id, Account>([
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountIds
            FOR UPDATE
        ]);

        if (lockedAccounts.isEmpty()) {
            return;
        }

        Set<Id> lockedAccountIds = lockedAccounts.keySet();
        Map<Id, Integer> countsByAccountId = new Map<Id, Integer>();

        for (AggregateResult result : [
            SELECT AccountId, COUNT(Id) openCount
            FROM Case
            WHERE AccountId IN :lockedAccountIds
                AND IsClosed = false
            GROUP BY AccountId
        ]) {
            countsByAccountId.put(
                (Id) result.get('AccountId'),
                (Integer) result.get('openCount')
            );
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Account parent : lockedAccounts.values()) {
            Integer openCount = countsByAccountId.get(parent.Id);

            // Accounts with no open cases have no aggregate result.
            if (openCount == null) {
                openCount = 0;
            }

            if (parent.FB_Open_Case_Count__c != openCount) {
                accountsToUpdate.add(new Account(
                    Id = parent.Id,
                    FB_Open_Case_Count__c = openCount
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            // All-or-none: a failed rollup must also fail the Case operation.
            update accountsToUpdate;
        }
    }
}
