public with sharing class TA_Opportunity_LogAmountChange
    implements TriggerAction.AfterUpdate {

    // Static state survives action re-instantiation and recursive trigger execution.
    private static final Set<Id> loggedOpportunityIds = new Set<Id>();

    public void afterUpdate(
        List<Opportunity> triggerNew,
        List<Opportunity> triggerOld
    ) {
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>(triggerOld);
        List<Task> tasksToInsert = new List<Task>();
        Set<Id> reservedThisExecution = new Set<Id>();

        for (Opportunity opp : triggerNew) {
            // Apex equality handles changes to and from null.
            if (opp.Amount == oldById.get(opp.Id).Amount
                || loggedOpportunityIds.contains(opp.Id)) {
                continue;
            }

            tasksToInsert.add(new Task(
                Subject = 'Amount changed',
                WhatId = opp.Id,
                Status = 'Completed'
            ));

            // Reserve before DML, since Task automation could also cause re-entry.
            loggedOpportunityIds.add(opp.Id);
            reservedThisExecution.add(opp.Id);
        }

        if (tasksToInsert.isEmpty()) {
            return;
        }

        try {
            // Mandatory audit automation intentionally uses system-mode DML.
            // All-or-none: audit failures must not silently allow the update.
            insert tasksToInsert;
        } catch (DmlException ex) {
            loggedOpportunityIds.removeAll(reservedThisExecution);
            throw ex;
        }
    }
}
